G_GUARD.append(T("guardrail_rule",
    "EN-17-38 Quy tắc bộ lọc vào hoặc ra (FR-17-044…046; BR-17-059, 060, 063): loại INPUT hoặc OUTPUT, mẫu (REGEX, KEYWORD hoặc bộ phát hiện), hành động BLOCK, MASK, WARN. Quy tắc dựng sẵn (builtin) không xóa, không đổi mã; chỉ tắt, bật có kiểm toán.",
    ["rule_code varchar(48) NOT NULL", "guardrail_kind varchar(8) NOT NULL", "action varchar(8) NOT NULL", "category varchar(20) NOT NULL", "pattern_kind varchar(10) NOT NULL", "pattern text NOT NULL",
     "description varchar(1000)", "enabled boolean NOT NULL DEFAULT true", "builtin boolean NOT NULL DEFAULT false"],
    [("uq_guardrail_rule_code", "UNIQUE (tenant_id, rule_code)"), chk("guardrail_rule", "code", "rule_code ~ '^GR-(IN|OUT)-[A-Z0-9-]{3,40}$'"),
     chk("guardrail_rule", "kind", f"guardrail_kind IN {E('GuardrailKind')}"), chk("guardrail_rule", "action", f"action IN {E('GuardrailAction')}"),
     chk("guardrail_rule", "category", "category IN ('PROMPT_INJECTION', 'FORBIDDEN', 'PII', 'SECRET', 'LINK')"),
     chk("guardrail_rule", "pattern_kind", "pattern_kind IN ('REGEX', 'KEYWORD', 'DETECTOR')"),
     chk("guardrail_rule", "kind_code", "(guardrail_kind = 'INPUT') = (rule_code LIKE 'GR-IN-%')"),
     chk("guardrail_rule", "secret_blocks", "category <> 'SECRET' OR (guardrail_kind = 'OUTPUT' AND action = 'BLOCK')"),
     chk("guardrail_rule", "inject_blocks", "category NOT IN ('PROMPT_INJECTION', 'FORBIDDEN') OR (guardrail_kind = 'INPUT' AND action = 'BLOCK')"),
     chk("guardrail_rule", "pattern", "char_length(pattern) BETWEEN 1 AND 4000")],
    idx=[f"CREATE INDEX ix_guardrail_rule_kind ON {S}.guardrail_rule (tenant_id, guardrail_kind, enabled);"],
    tid=True, trig=[("immutable", ["rule_code", "guardrail_kind", "builtin"])],
    ccomment={"pattern": "REGEX hoặc từ khóa; với DETECTOR là mã bộ phát hiện (injection-classifier, sensitive-pii). Mẫu bí mật chỉ mô tả dạng, không giá trị thật."}))

